begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
select throws_ok($$insert into public.quotes(job_id,worker_id,pricing_type,status,subtotal_cents,total_cents,scope) values ('50000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000003','fixed','submitted',1,1,'Invalid cross-worker quote')$$,'23503',null,'quote must reference the same job-worker match');
select throws_ok($$insert into public.bookings(job_id,quote_id,worker_id,final_total_cents) values ('50000000-0000-0000-0000-000000000003','70000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002',10000)$$,'P0001',null,'cannot use a quote from another job');
select throws_ok($$insert into public.bookings(job_id,quote_id,worker_id,final_total_cents) values ('50000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002',10000)$$,'23505',null,'one booking per job enforced');
select throws_ok($$update public.bookings set final_total_cents=1$$,'P0001',null,'accepted booking amount cannot be changed');
insert into public.quotes(id,job_id,worker_id,pricing_type,status,scope) values ('70000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000003','30000000-0000-0000-0000-000000000002','inspection_required','accepted','Synthetic inspection-only quote');
select throws_ok($$insert into public.bookings(job_id,quote_id,worker_id,final_total_cents) values ('50000000-0000-0000-0000-000000000003','70000000-0000-0000-0000-000000000003','30000000-0000-0000-0000-000000000002',10000)$$,'P0001',null,'inspection cannot silently become a priced work booking');
select throws_ok($$insert into public.quotes(job_id,worker_id,pricing_type,subtotal_cents,total_cents,scope) values ('50000000-0000-0000-0000-000000000003','30000000-0000-0000-0000-000000000002','fixed',1000,1,'Invalid total')$$,'23514',null,'fixed quote total must match components');
select throws_ok($$update private.audit_events set action='tampered'$$,'P0001',null,'audit update rejected even for database administrator');
select throws_ok($$delete from private.audit_events$$,'P0001',null,'audit delete rejected');
select throws_ok($$truncate private.audit_events$$,'P0001',null,'audit truncate rejected');
select throws_ok($$update private.payment_ledger set amount_cents=0$$,'P0001',null,'ledger is append-only');
set local role service_role;
select throws_ok($$update private.audit_events set action='tampered'$$,'42501',null,'service role lacks audit mutation grant');
reset role;
select throws_ok($$select private.publish_worker_card('30000000-0000-0000-0000-000000000005','40000000-0000-0000-0000-000000000001','Suspended fixture',null)$$,'P0001',null,'suspended worker cannot be published');
select throws_ok($$select private.publish_worker_card('30000000-0000-0000-0000-000000000006','40000000-0000-0000-0000-000000000001','Pending fixture',null)$$,'P0001',null,'pending worker cannot be published');
select throws_ok($$update public.worker_cards set approx_marker=extensions.st_setsrid(extensions.st_makepoint(30.001,-27.001),4326)::extensions.geography$$,'P0001',null,'private base cannot be used as public marker');
update private.worker_verifications set expiry_date=current_date-1 where worker_id='30000000-0000-0000-0000-000000000002' and kind='trade';
select is((select count(*)::integer from public.worker_cards),0,'credential change unpublishes existing card');
select throws_ok($$select private.publish_worker_card('30000000-0000-0000-0000-000000000002','40000000-0000-0000-0000-000000000001','Expired fixture',null)$$,'P0001',null,'expired trade credential blocks category publication');
-- A valid non-regulated category remains eligible without falsely claiming a trade badge.
insert into public.worker_services(worker_id,category_id,title,price_model) values ('30000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002','Synthetic cleaning','quote');
select private.publish_worker_card('30000000-0000-0000-0000-000000000002','40000000-0000-0000-0000-000000000001','Fictional cleaning worker',null);
select is((select category_ids from public.worker_cards),array['20000000-0000-0000-0000-000000000002'::uuid],'only eligible categories published');
select is((select cardinality(verified_trade_category_ids) from public.worker_cards),0,'non-regulated category gets no trade badge');
update public.worker_profiles set status='suspended' where id='30000000-0000-0000-0000-000000000002';
select is((select count(*)::integer from public.worker_cards),0,'suspension immediately unpublishes card');
select throws_ok($$update public.quotes set subtotal_cents=1,total_cents=1 where id='70000000-0000-0000-0000-000000000001'$$,'P0001',null,'accepted quote cannot silently change under a booking');
select throws_ok($$insert into public.quote_items(quote_id,description,quantity,unit_price_cents) values ('70000000-0000-0000-0000-000000000001','Tampered item',1,1)$$,'P0001',null,'accepted quote cannot receive additional items');
insert into public.business_profiles(id,owner_id,display_name,status) values ('b0000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003','Fictional business','approved');
select throws_ok($$update public.worker_profiles set business_id='b0000000-0000-0000-0000-000000000001' where id='30000000-0000-0000-0000-000000000002'$$,'P0001',null,'worker cannot attach another identity business');
select * from finish();
rollback;
